/// <summary>
/// CB616_TMSEngineSOCancellation
/// CB624_TMSEngineSOCreation
/// Class to proceede with the cancellation process for TMS engine
/// </summary>
[METTMSEngineExecutionModeAttribute(METTMSEngineExecutionMode::SalesOrderCancellation)]
internal final class METTMSEngineSalesOrderProccess_Cancellation extends METTMSEngineOrderProccess
{
    SalesTable salesTable;

}

Method.Source:
/// <summary>
/// Refactored new validate method
/// </summary>
/// <returns>true if valdidation successful; otherwise, false.</returns>
protected boolean validate()
{       
    return salesTable.SalesStatus == SalesStatus::Canceled && super();
}

    /// <summary>
    /// Gets the execution mode of the process class
    /// </summary>
    /// <returns><c>METTMSEngineExecutionMode</c></returns>
    public METTMSEngineExecutionMode getExecutionMode()
    {
        METTMSEngineExecutionMode ret = METTMSEngineExecutionMode::SalesOrderCancellation;

        return ret;
    }

    /// <summary>
    ///
    /// </summary>
    /// <param name = "_sourceRecord"></param>
    protected void init(METTMSSourceRecordHeaderMap _sourceRecord)
    {
        super(_sourceRecord);

        salesTable = SalesTable::find(_sourceRecord.OrderId);
    }

/// <summary>
/// Run the TMS cancellation
/// </summary>
public void run()
{
    if (this.validate())
    {
        try
        {
            this.cancelShipment(headerContract.parmSourceRecord().OrderId);
        }
        catch (Exception::Error)
        {
            //SO should stay canceled even though TMS engine cancellation failed
            error(this.errorMessage());
        }
    }
}

/// <summary>
/// error message
/// </summary>
/// <returns>error txt</returns>
protected ErrorTxt errorMessage()
{
    return "@MET:TMSEngineSOCancellationError";
}
